// Generated by tools/fit/fit_knob_shadow.py: the plate knobs' shadow on the plate, fitted to the reference.
// factor(d, a) = 1 - max(0, amp(a)) * (w1 exp(-d/t1) + w2 exp(-d/t2)); d = design px beyond the knob edge,
// a = angle from up, clockwise; amp = c0 + c1 cos a + c2 sin a + c3 cos 2a + c4 sin 2a + c5 cos 3a + c6 sin 3a
#pragma once
#include <cmath>
#include <algorithm>

namespace dp::knobshadow
{
inline constexpr float c[7] { 0.26483f, -0.15751f, -0.37986f, -0.12639f, 0.14852f, 0.07013f, 0.02567f };
inline constexpr float w1 = 0.58384f, t1 = 10.0000f, w2 = 0.59730f, t2 = 27.9729f;
inline float factor (float d, float a)
{
    const float amp = c[0] + c[1] * std::cos (a) + c[2] * std::sin (a) + c[3] * std::cos (2 * a) + c[4] * std::sin (2 * a)
                    + c[5] * std::cos (3 * a) + c[6] * std::sin (3 * a);
    // never darker than measured right at the edge (0.27)
    return std::max (0.27f, 1.0f - std::max (0.0f, amp) * (w1 * std::exp (-d / t1) + w2 * std::exp (-d / t2)));
}
}
